from typing import List

def chooseMaxMinRating(n: int, m: int, ratings: List[List[int]]) -> int:
    # ratings[i][j]：第 i 个顾客给第 j 个产品的评分；要选 n-2 个产品（假设 n >= 3）

    def feasible(t: int) -> bool:
        covered = [False] * n
        has3 = False
        edges = []                               # 恰好被 2 个顾客打到 >= t 的产品
        for j in range(m):
            who = [i for i in range(n) if ratings[i][j] >= t]
            for i in who:
                covered[i] = True
            if len(who) >= 3:
                has3 = True
            elif len(who) == 2:
                edges.append((who[0], who[1]))
        if not all(covered):
            return False
        if has3:
            return True
        if not edges:
            return False
        # 是否存在两条不相交的边
        a, b = edges[0]
        xs, ys = set(), set()
        for u, v in edges:
            if u not in (a, b) and v not in (a, b):
                return True
            for p, q in ((u, v), (v, u)):
                if p == a and q != b:
                    xs.add(q)
                if p == b and q != a:
                    ys.add(q)
        return bool(xs) and bool(ys) and len(xs | ys) >= 2

    vals = sorted({v for row in ratings for v in row})
    lo, hi = 0, len(vals) - 1                    # vals[0] 一定可行
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(vals[mid]):
            lo = mid
        else:
            hi = mid - 1
    return vals[lo]
